from __future__ import annotations

import ast
import hashlib
import importlib
import inspect
import json
import re
import sys
from pathlib import Path
from typing import get_type_hints

ROOT = Path(__file__).resolve().parents[1]
BACKEND = ROOT / "backend"
sys.path.insert(0, str(BACKEND))
OUT = ROOT / "docs/audit/dashboard-2026-10-30"
TARGET = BACKEND / "app/presentation/api/v1/routes/passport_routes/contact_verification.py"
TEST = BACKEND / "tests/unit/presentation/test_public_upload_contact_otp.py"
PREFIX = "app.presentation.api.v1.routes.passport_routes."
FUNCTIONS = ["_no_store", "_locked_upload", "_locked_challenge", "request_public_contact_otp", "verify_public_contact_otp", "require_public_contact_proof", "require_verified_family_head"]


def sha(raw: bytes) -> str:
    return hashlib.sha256(raw).hexdigest()


def snapshot() -> dict:
    from fastapi import FastAPI
    module = importlib.import_module(PREFIX + "contact_verification")
    app = FastAPI()
    app.include_router(module.router)
    return {
        "openapi": app.openapi(),
        "functions": {
            name: {
                "signature": str(inspect.signature(getattr(module, name))),
                "evaluated_type_hints": {
                    key: repr(value) for key, value in get_type_hints(getattr(module, name)).items()
                },
            }
            for name in FUNCTIONS
        },
        "routes": [
            {
                "path": route.path,
                "name": route.name,
                "methods": sorted(route.methods),
                "dependencies": [str(inspect.signature(dep.call)) for dep in route.dependant.dependencies],
                "headers": [field.name for field in route.dependant.header_params],
            }
            for route in module.router.routes
        ],
    }


if __name__ == "__main__":
    mode = sys.argv[1]
    if mode == "before":
        raw = TARGET.read_bytes()
        assert sha(raw) == "f44ded4789d0886c91c2612485d761e5d453f6e813e5b2386df925e671649ae5"
        original = {"path": str(TARGET.relative_to(ROOT)).replace("\\", "/"), "sha256": sha(raw), "source": raw.decode("utf-8"), "test_sha256": sha(TEST.read_bytes()), "test_source": TEST.read_bytes().decode("utf-8")}
        (OUT / "contact-verification-original-source.json").write_text(json.dumps(original, indent=2) + "\n", encoding="utf-8")
    baseline = OUT / "contact-verification-original-runtime-contract.json"
    current = snapshot()
    if mode == "before":
        baseline.write_text(json.dumps(current, indent=2) + "\n", encoding="utf-8")
    else:
        before = json.loads(baseline.read_text(encoding="utf-8"))
        normalized = json.loads(json.dumps(current))
        # inspect's Depends repr embeds a process-specific address. Preserve
        # both raw snapshots and normalize only that dependency's address.
        for document in [before, normalized]:
            for value in document["functions"].values():
                value["signature"] = re.sub(r"get_db_session at 0x[0-9A-Fa-f]+", "get_db_session at <process-address>", value["signature"])
        assert normalized == before
        (OUT / "contact-verification-current-runtime-contract.json").write_text(json.dumps(current, indent=2) + "\n", encoding="utf-8")
    print(json.dumps({"mode": mode, "evaluated_functions": len(FUNCTIONS), "routes": len(current["routes"]), "openapi_equal": mode != "before"}))
